package com.yosmitha.enterprise_iam.service;
import com.yosmitha.enterprise_iam.config.JwtService;import com.yosmitha.enterprise_iam.dto.ApiDtos.*;import com.yosmitha.enterprise_iam.entity.*;import com.yosmitha.enterprise_iam.exception.ApiException;import com.yosmitha.enterprise_iam.repository.*;import com.warrenstrange.googleauth.GoogleAuthenticator;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.security.*;import java.nio.charset.StandardCharsets;import java.util.*;
@Service public class IamService{
 final UserRepository users;final RoleRepository roles;final PermissionRepository permissions;final OneTimeTokenRepository tokens;final RefreshSessionRepository sessions;final AuditLogRepository audits;final PasswordEncoder encoder;final JwtService jwt;final long refreshDays;final GoogleAuthenticator ga=new GoogleAuthenticator();
 public IamService(UserRepository u,RoleRepository r,PermissionRepository p,OneTimeTokenRepository t,RefreshSessionRepository s,AuditLogRepository a,PasswordEncoder e,JwtService j,@Value("${app.jwt.refresh-days}")long d){users=u;roles=r;permissions=p;tokens=t;sessions=s;audits=a;encoder=e;jwt=j;refreshDays=d;}
 void audit(Long id,String action,String target,String details){audits.save(new AuditLog(id,action,target,details));}
 @Transactional public Message register(Register x){if(users.existsByEmail(x.email()))throw new ApiException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.setFirstName(x.firstName());u.setLastName(x.lastName());u.setEmail(x.email());u.setPasswordHash(encoder.encode(x.password()));roles.findByName("USER").ifPresent(u.getRoles()::add);users.save(u);String t=UUID.randomUUID().toString();tokens.save(new OneTimeToken(t,u,Instant.now().plusSeconds(86400),"VERIFY"));audit(u.getId(),"REGISTER",u.getEmail(),"Verification token generated");return new Message("Registered. Development verification token: "+t);}
 @Transactional public Message verify(Token x){OneTimeToken t=tokens.findByTokenAndPurpose(x.token(),"VERIFY").orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Invalid token"));if(t.getExpiresAt().isBefore(Instant.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"Token expired");t.getUser().setEmailVerified(true);t.getUser().setEnabled(true);tokens.delete(t);audit(t.getUser().getId(),"EMAIL_VERIFIED",t.getUser().getEmail(),"Verified");return new Message("Email verified");}
 List<String> authorities(User u){return u.getRoles().stream().flatMap(r->java.util.stream.Stream.concat(java.util.stream.Stream.of("ROLE_"+r.getName()),r.getPermissions().stream().map(Permission::getName))).distinct().toList();}
 String hash(String s){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 @Transactional public TokenPair login(Login x,String ua,String ip){User u=users.findByEmail(x.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(u.getLockedUntil()!=null&&u.getLockedUntil().isBefore(Instant.now())){u.setLockedUntil(null);u.setAccountNonLocked(true);u.setFailedLoginAttempts(0);}if(!u.isEnabled()||!u.isEmailVerified()||!u.isAccountNonLocked())throw new ApiException(HttpStatus.LOCKED,"Account unavailable or locked");if(!encoder.matches(x.password(),u.getPasswordHash())){int n=u.getFailedLoginAttempts()+1;u.setFailedLoginAttempts(n);if(n>=5){u.setAccountNonLocked(false);u.setLockedUntil(Instant.now().plusSeconds(900));}audit(u.getId(),"LOGIN_FAILED",u.getEmail(),"Bad password");throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}if(u.isMfaEnabled()){int code;try{code=Integer.parseInt(x.otp());}catch(Exception e){code=-1;}if(!ga.authorize(u.getMfaSecret(),code))throw new ApiException(HttpStatus.UNAUTHORIZED,"MFA code required/invalid");}u.setFailedLoginAttempts(0);String a=jwt.access(u.getEmail(),u.getId(),authorities(u)),r=jwt.refresh(u.getEmail(),u.getId(),refreshDays);sessions.save(new RefreshSession(u,hash(r),Instant.now().plusSeconds(refreshDays*86400),ua,ip));audit(u.getId(),"LOGIN_SUCCESS",u.getEmail(),"Session created");return new TokenPair(a,r,"Bearer",jwt.expires());}
 @Transactional public TokenPair refresh(Refresh x,String ua,String ip){RefreshSession s=sessions.findByTokenHash(hash(x.refreshToken())).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid refresh token"));if(s.getRevokedAt()!=null||s.getExpiresAt().isBefore(Instant.now()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Refresh token expired/revoked");s.setRevokedAt(Instant.now());User u=s.getUser();String a=jwt.access(u.getEmail(),u.getId(),authorities(u)),r=jwt.refresh(u.getEmail(),u.getId(),refreshDays);sessions.save(new RefreshSession(u,hash(r),Instant.now().plusSeconds(refreshDays*86400),ua,ip));return new TokenPair(a,r,"Bearer",jwt.expires());}
 @Transactional public Message logout(Refresh x){sessions.findByTokenHash(hash(x.refreshToken())).ifPresent(s->s.setRevokedAt(Instant.now()));return new Message("Session revoked");}
 @Transactional public Message forgot(Forgot x){users.findByEmail(x.email()).ifPresent(u->{String t=UUID.randomUUID().toString();tokens.save(new OneTimeToken(t,u,Instant.now().plusSeconds(1800),"RESET"));audit(u.getId(),"PASSWORD_RESET_REQUESTED",u.getEmail(),"Token created");});return new Message("If account exists, reset instructions were issued.");}
 @Transactional public Message reset(Reset x){OneTimeToken t=tokens.findByTokenAndPurpose(x.token(),"RESET").orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"Invalid reset token"));if(t.getExpiresAt().isBefore(Instant.now()))throw new ApiException(HttpStatus.BAD_REQUEST,"Token expired");User u=t.getUser();u.setPasswordHash(encoder.encode(x.newPassword()));tokens.delete(t);sessions.findByUserIdAndRevokedAtIsNull(u.getId()).forEach(s->s.setRevokedAt(Instant.now()));audit(u.getId(),"PASSWORD_RESET",u.getEmail(),"Password reset; sessions revoked");return new Message("Password reset");}
 @Transactional public Map<String,String> setupMfa(String email){User u=users.findByEmail(email).orElseThrow();String secret=ga.createCredentials().getKey();u.setMfaSecret(secret);return Map.of("secret",secret,"otpauthUrl","otpauth://totp/EnterpriseIAM:"+email+"?secret="+secret+"&issuer=EnterpriseIAM");}
 @Transactional public Message enableMfa(String email,MfaCode x){User u=users.findByEmail(email).orElseThrow();int c;try{c=Integer.parseInt(x.code());}catch(Exception e){c=-1;}if(u.getMfaSecret()==null||!ga.authorize(u.getMfaSecret(),c))throw new ApiException(HttpStatus.BAD_REQUEST,"Invalid TOTP");u.setMfaEnabled(true);return new Message("MFA enabled");}
 @Transactional public Message disableMfa(String email){User u=users.findByEmail(email).orElseThrow();u.setMfaEnabled(false);u.setMfaSecret(null);return new Message("MFA disabled");}
 @Transactional public Map<String,Object> profile(String email,Profile p){User u=users.findByEmail(email).orElseThrow();if(p!=null){u.setFirstName(p.firstName());u.setLastName(p.lastName());audit(u.getId(),"PROFILE_UPDATED",email,"Profile updated");}return Map.of("id",u.getId(),"firstName",u.getFirstName(),"lastName",u.getLastName(),"email",u.getEmail(),"emailVerified",u.isEmailVerified(),"mfaEnabled",u.isMfaEnabled(),"roles",u.getRoles().stream().map(Role::getName).toList());}
 @Transactional public Role addRole(String name,String description){return roles.save(new Role(name.toUpperCase(),description));}
 @Transactional public Permission addPermission(String name,String description){return permissions.save(new Permission(name,description));}
 @Transactional public void assignRole(Long uid,Long rid){User u=users.findById(uid).orElseThrow();Role r=roles.findById(rid).orElseThrow();u.getRoles().add(r);audit(u.getId(),"ROLE_ASSIGNED",u.getEmail(),r.getName());}
 @Transactional public void grant(Long rid,Long pid){Role r=roles.findById(rid).orElseThrow();r.getPermissions().add(permissions.findById(pid).orElseThrow());}
 @Transactional public void enable(Long id,boolean value){User u=users.findById(id).orElseThrow();u.setEnabled(value);}
}
